/* Tsela Yagwe Network — WebDevPro full-stack-ready website. No test wallets or fake transactions. */
'use strict';
const config=window.TSELA_CONFIG||{};
const SB=config.supabaseUrl?.replace(/\/$/,'')||'', KEY=config.supabasePublishableKey||'';
const CONNECTED=Boolean(SB&&KEY);
const app=document.querySelector('#app');
const state={route:location.pathname||'/',user:null,profile:null,session:null,courses:null,commodities:null,listings:null,orders:[],enrollments:[],transactions:[],capitalRequests:[],dashTab:'overview',adminTab:'enrollments',priceFilter:'All',listingFilter:'All',notice:'',installPrompt:null};
const coursesSeed=[
{slug:'investor-development',title:'Investor Development Course',short_description:'Understand impact investment, due diligence, capital structure and the fundamentals of investment-ready ventures.',duration:'Enquire for schedule',fee:null,icon:'📈',image:'https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=1100&q=82'},
{slug:'advanced-tech-development',title:'Advanced Tech Development Course',short_description:'Develop applied digital, emerging technology and data skills for practical enterprises and modern agriculture.',duration:'Enquire for schedule',fee:null,icon:'💻',image:'https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=1100&q=82'},
{slug:'franchise-crop-production',title:'Franchise Crop Production Course',short_description:'Learn how to plan, launch and manage a crop-production franchise with sound commercial and operational practices.',duration:'Enquire for schedule',fee:null,icon:'🌱',image:'https://images.unsplash.com/photo-1464226184884-fa280b87c399?w=1100&q=82'}
];
const crops=[{name:'Maize',category:'Crops',unit:'kg'},{name:'Sorghum',category:'Crops',unit:'kg'},{name:'Cattle',category:'Livestock',unit:'kg'},{name:'Goats',category:'Livestock',unit:'kg'},{name:'Poultry',category:'Livestock',unit:'kg'},{name:'Sheep',category:'Livestock',unit:'kg'},{name:'Vegetables',category:'Crops',unit:'kg'},{name:'Groundnuts',category:'Crops',unit:'kg'}];
const finance=['Individual Impact Investors','Institutional Impact Investors','National Empowerment & Development Funds'];
const pathways=[{name:'Franchise Trainer',description:'Train and mentor new entrepreneurs within structured franchise programmes.'},{name:'Commodity Manager',description:'Support commodity sourcing, pricing, quality and market coordination.'},{name:'Sales Broker',description:'Connect producers and verified buyers and manage market enquiries.'},{name:'Franchise Applicant',description:'Apply to develop and operate an approved franchise opportunity.'}];
const formatZar=n=>'R '+Number(n||0).toLocaleString('en-ZA',{minimumFractionDigits:2,maximumFractionDigits:2});
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const phone=config.whatsapp||'27651503974';
const wa=(s='Hello, I would like to know more about Tsela Yagwe Network.')=>'https://wa.me/'+phone+'?text='+encodeURIComponent(s);
const nav=[['/','Home'],['/about','About Us'],['/courses','Courses'],['/fees','Course Fees'],['/financing','Financing'],['/enrollment','Enrollment'],['/markets','Markets'],['/contact','Contact']];
const a=(href,label,klass='')=>`<a href="${href}" class="${klass}" data-link>${label}</a>`;
const title=(eyebrow,heading,desc='')=>`<div class="page-hero"><div class="container"><div class="breadcrumb">Tsela Yagwe Network / ${esc(eyebrow)}</div><h1>${heading}</h1><p>${esc(desc)}</p></div></div>`;
const field=(id,label,ph='',type='text',required=true)=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" placeholder="${esc(ph)}" ${required?'required':''} ${type==='email'?'autocomplete="email"':''}></div>`;
function header(){let link=state.route;return `<header class="site-header"><div class="topbar">LEARNING • FRANCHISE DEVELOPMENT • AGRICULTURAL MARKETS • IMPACT INVESTMENT READINESS</div><div class="container nav"><a href="/" data-link class="brand"><span class="brand-mark">TY</span><span><strong>TSELA YAGWE</strong><small>NETWORK</small></span></a><nav class="navlinks">${nav.map(([p,t])=>a(p,t,link===p?'active':'')).join('')}</nav><div class="nav-cta">${a(state.user?'/dashboard':'/login',state.user?'Dashboard':'Login','btn btn-outline btn-sm')}${a('/enrollment','Apply Now','btn btn-primary btn-sm')}</div><button class="hamburger" id="menuButton" aria-label="Open navigation" aria-expanded="false">☰</button></div><div id="mobileDrawer" class="mobile-drawer hide">${nav.map(([p,t])=>a(p,t)).join('')}${a(state.user?'/dashboard':'/login',state.user?'My Dashboard':'Login / Register')}${a('/enrollment','Apply for Training')}</div></header>`}
function footer(){return `<footer class="footer"><div class="container grid grid4"><div><div class="brand"><span class="brand-mark">TY</span><span><strong>TSELA YAGWE</strong><small>NETWORK</small></span></div><p style="margin-top:20px">Transforming learning opportunities and challenged business cases into meaningful impact investment cases.</p><img src="https://static.wixstatic.com/media/92fe26_d7cbb3fcea4045f7a165961d98a4dc69~mv2.png" alt="Markets Online" loading="lazy" style="width:120px;border-radius:12px;background:white;padding:7px;margin-top:10px"></div><div><h4>Explore</h4><div class="footer-links">${a('/about','About the Network')}${a('/courses','Development Courses')}${a('/enrollment','Course Enrollment')}${a('/financing','Course Financing')}</div></div><div><h4>Markets Online</h4><div class="footer-links">${a('/markets','Commodity Marketplace')}${a('/prices','Market Price Indicators')}${a('/dashboard','Member Dashboard')}${a('/register','Create Account')}</div></div><div><h4>Get in touch</h4><p>Enquiries and partnership opportunities</p><div class="footer-links"><a href="${wa()}" target="_blank" rel="noopener">WhatsApp: +27 65 150 3974</a>${a('/contact','Contact Form')}</div></div></div><div class="container footer-bottom flex between wrap"><span>© ${new Date().getFullYear()} Tsela Yagwe Network. All rights reserved.</span><span class="footer-bottom-right">Website designed by <a href="https://webdevpro.co.za" target="_blank" rel="noopener">WebDevPro</a> · <a href="https://wdphosting.com" target="_blank" rel="noopener">WDPHosting</a><a href="/admin" data-link class="footer-admin" aria-label="Administrator login"><span aria-hidden="true">⚙</span> Admin</a></span></div></footer>`}
function feature(image,eyebrow,name,desc,href,linkName='Learn more'){return `<article class="feature-card"><img loading="lazy" src="${image}" alt="${esc(name)}"><div class="feature-body"><div class="eyebrow">${eyebrow}</div><h3>${esc(name)}</h3><p>${esc(desc)}</p>${a(href,linkName+' →','text-link')}</div></article>`}
function courseCard(c){return `<article class="course-card"><div class="course-icon">${c.icon||'🎓'}</div><div class="eyebrow">SKILLS DEVELOPMENT</div><h3>${esc(c.title)}</h3><p>${esc(c.short_description)}</p><div class="course-meta">${esc(c.duration||'Dates on request')} · ${c.fee==null?'Fees confirmed on enquiry':formatZar(c.fee)}</div>${a('/enrollment?course='+encodeURIComponent(c.slug),'Apply for this course →','text-link')}</article>`}
function home(){return `<section class="hero"><div class="container"><div class="hero-content"><div class="eyebrow" style="color:#f1c98e">BUILD KNOWLEDGE. GROW ENTERPRISE. CREATE IMPACT.</div><h1>Grow the future through <em>learning and opportunity.</em></h1><p>We connect practical development courses, franchise opportunities and agricultural markets — helping ideas and challenged business cases become investment-ready enterprises.</p><div class="button-row" style="margin-top:32px">${a('/courses','Explore Our Courses →','btn btn-white')}${a('/markets','Visit Markets Online','btn btn-dark-outline')}</div><div class="hero-tags"><span>Investor Development</span><span>Advanced Technology</span><span>Crop Production</span><span>Commodity Markets</span></div></div></div></section><div class="stat-band"><div class="stat"><strong>3</strong><span>Focused learning pathways</span></div><div class="stat"><strong>4</strong><span>Enrollment and franchise tracks</span></div><div class="stat"><strong>1 Network</strong><span>Connecting education, enterprise and markets</span></div></div>
<section class="section"><div class="container"><div class="flex between wrap mb"><div class="heading"><div class="eyebrow">OUR ECOSYSTEM</div><h2>From skills to sustainable enterprise.</h2><p class="lead">One connected platform to discover training, explore real agricultural opportunities and build pathways for commercial growth.</p></div>${a('/about','How the network works →','text-link')}</div><div class="grid grid3">${feature('https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=1100&q=82','01 / LEARN','Entrepreneurial Development','Courses designed around impact investors, advanced technology and agricultural franchises.','/courses')}${feature('https://images.unsplash.com/photo-1464226184884-fa280b87c399?w=1100&q=82','02 / PRODUCE','Franchise Crop Production','Build operational knowledge across crop production and market-ready agricultural enterprises.','/enrollment')}${feature('https://images.unsplash.com/photo-1546445317-29f4545e9d53?w=1100&q=82','03 / TRADE','Markets Online','Discover crop and livestock listings, commodity price indicators and trading enquiries.','/markets')}</div></div></section>
<section class="section soft"><div class="container split"><div class="image-panel"><img loading="lazy" src="https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=1100&q=82" alt="African agribusiness professionals learning together"><div class="overlay-label">Learning that connects opportunity with real-world enterprise.</div></div><div><div class="eyebrow">ABOUT TSELA YAGWE NETWORK</div><h2>We turn potential into investable opportunity.</h2><p class="lead">Our expertise is to transform learning opportunities and challenged business cases into impact investment cases. We support prospective investors, franchise developers, agribusiness professionals and enterprise partners.</p><div class="step"><div class="number">01</div><div><h4>Learn with purpose</h4><p>Develop the right knowledge for your preferred enterprise or investment pathway.</p></div></div><div class="step"><div class="number">02</div><div><h4>Build a commercially sound case</h4><p>Advance your enterprise model and understand feasibility, risk and opportunity.</p></div></div><div class="step"><div class="number">03</div><div><h4>Connect to the marketplace</h4><p>Explore agricultural sourcing, buyers, finance discussions and collaboration.</p></div></div><div style="margin-top:25px">${a('/about','Discover our mission →','btn btn-primary')}</div></div></div></section>
<section class="section light"><div class="container"><div class="center"><div class="eyebrow">FEATURED LEARNING</div><h2>Find your next development course</h2><p class="lead" style="margin:0 auto 35px">Practical learning pathways for investors, technology professionals and agricultural entrepreneurs.</p></div><div class="grid grid3">${(state.courses?.length?state.courses:coursesSeed).slice(0,3).map(courseCard).join('')}</div><div class="center mt">${a('/courses','View all courses →','btn btn-outline')}</div></div></section>
<section class="section"><div class="container"><div class="cta-box"><div class="eyebrow" style="color:#e9c88d">TAKE THE NEXT STEP</div><h2>Your future in business can begin here.</h2><p>Whether you're exploring a course, developing a franchise or sourcing agricultural commodities, our team can help guide your next move.</p><div class="button-row">${a('/enrollment','Start your enrollment →','btn btn-white')}<a href="${wa('Hello, I would like to enquire about Tsela Yagwe Network courses and opportunities.')}" target="_blank" rel="noopener" class="btn btn-dark-outline">Speak to an advisor</a></div></div></div></section>`}
function about(){return `${title('About Us','Developing people. Connecting enterprises.','Our expertise is to transform learning opportunities and challenged business cases into impact investment cases.')}<section class="section"><div class="container split"><div><div class="eyebrow">WHO WE ARE</div><h2>An ecosystem built for opportunity.</h2><p class="lead">Tsela Yagwe Network brings together investor development, advanced technology development, crop-production franchise pathways and agricultural commodity markets.</p><p>We believe that practical knowledge, sound commercial processes and meaningful connections can help communities and businesses participate more effectively in the economy.</p><div class="notice">Programme admissions, financing and all capital-related arrangements remain subject to eligibility reviews, applicable terms and independent verification. No investment returns are guaranteed.</div></div><div class="image-panel"><img src="https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=1400&q=82" alt="Agricultural entrepreneur looking across a cultivated farm"><div class="overlay-label">Empowering learning and enterprise growth.</div></div></div></section><section class="section soft"><div class="container grid grid3"><div class="course-card"><div class="course-icon">🎯</div><h3>Our focus</h3><p>Transform business cases into investable opportunities through education and commercial development.</p></div><div class="course-card"><div class="course-icon">🤝</div><h3>Our network</h3><p>Connect learners, franchise applicants, commodity professionals, traders and potential funding partners.</p></div><div class="course-card"><div class="course-icon">🌍</div><h3>Our vision</h3><p>Increase access to credible skills, market participation and sustainable enterprise opportunities across Africa.</p></div></div></section>`}
function courses(){let items=state.courses?.length?state.courses:coursesSeed;return `${title('Courses','Practical courses for a changing economy.','Discover learning pathways that connect education to enterprise development, responsible investment and agricultural production.')}<section class="section"><div class="container"><div class="eyebrow">COURSE CATALOGUE</div><h2>Choose your development pathway</h2><p class="lead">Select a course to begin the application process. Enrolment dates, requirements and fees will be confirmed by the programme coordinator.</p><div class="grid grid3 mt">${items.map(courseCard).join('')}</div></div></section><section class="section-sm soft"><div class="container split"><div><div class="eyebrow">LEARNING WITH PURPOSE</div><h2>From skills to applied results.</h2><p class="lead">Our course portfolio is organised around understanding investment, using emerging technologies and creating production-ready franchise operations.</p>${a('/enrollment','Apply for a learning pathway →','btn btn-primary')}</div><img style="border-radius:22px;height:350px;object-fit:cover;width:100%" src="https://images.unsplash.com/photo-1464226184884-fa280b87c399?w=1100&q=82" alt="Hands planting crop seedlings"></div></section>`}
function fees(){return `${title('Course Fees','Clear pathways to planning your training.','View the two standard fee categories and request an up-to-date quotation for your chosen course.')}<section class="section"><div class="container grid grid2"><div class="course-card"><div class="course-icon">📝</div><div class="eyebrow">3.1 COURSE FEES</div><h3>Registration Fees</h3><p>Registration fees, where applicable, cover application processing and programme onboarding. Amounts and refund terms must be confirmed in writing before payment.</p><span class="pill gold">Current amount: on request</span></div><div class="course-card"><div class="course-icon">🎓</div><div class="eyebrow">3.2 COURSE FEES</div><h3>Tuition Fees</h3><p>Tuition fees vary according to your selected course, programme structure and confirmed intake. Receive the official fee schedule before committing.</p><span class="pill gold">Current amount: on request</span></div></div><div class="container mt"><div class="notice">No course fee figures were supplied for this project. We have deliberately not invented fees or enabled online collections. Request the verified 2026 fee schedule.</div><div class="button-row mt">${a('/contact','Request the course fee schedule →','btn btn-primary')}${a('/financing','Explore financing options','btn btn-outline')}</div></div></section>`}
function financing(){return `${title('Course Financing','Support for your learning ambitions.','Explore potential pathways to finance course registration and tuition through eligible funding partners.')}<section class="section"><div class="container"><div class="grid grid3">${finance.map((f,i)=>`<div class="course-card"><div class="course-icon">${['👤','🏛️','🌍'][i]}</div><div class="eyebrow">FINANCING OPTION 0${i+1}</div><h3>${f}</h3><p>${['Explore private support from individual impact investors, subject to investor assessment and agreement.','Explore potential support from institutional partners with relevant mandates and eligibility criteria.','Ask about suitable national empowerment, skills and enterprise-development programmes.'][i]}</p>${a('/contact','Enquire about eligibility →','text-link')}</div>`).join('')}</div><div class="notice mt">Funding is not automatically approved or guaranteed. Applicants should verify funding providers, formal terms, and regulatory requirements independently before signing or transferring money.</div></div></section>`}
function enrollment(){let course=new URLSearchParams(location.search).get('course')||'';return `${title('Enrollment','Start your application.','Choose the pathway that best fits your goals and send your details for review.')}<section class="section"><div class="container split" style="align-items:start"><div class="form-card"><h2>Enrollment application</h2><p class="muted">A programme coordinator will need to confirm the requirements, fees and available intake before admission.</p>${!CONNECTED?'<div class="notice mbs">Application requests will open WhatsApp until the secure database is connected. Nothing is stored on this preview website.</div>':''}<form id="enrollmentForm">${field('full_name','Full name','Your full name')}${field('email','Email address','you@example.com','email')}${field('mobile','Mobile / WhatsApp','+27 65 000 0000','tel')}<div class="field"><label for="course">Preferred course</label><select name="course" id="course" required><option value="">Select a course</option>${(state.courses?.length?state.courses:coursesSeed).map(c=>`<option value="${esc(c.slug)}" ${course===c.slug?'selected':''}>${esc(c.title)}</option>`).join('')}</select></div><div class="field"><label for="pathway">Applicant pathway</label><select id="pathway" name="pathway" required><option value="">Choose your track</option>${pathways.map(p=>`<option value="${esc(p.name)}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="motivation">Tell us about your interests</label><textarea id="motivation" name="motivation" rows="4" placeholder="What would you like to achieve through this programme?"></textarea></div><label style="font-size:.75rem;display:flex;gap:10px;margin-bottom:16px"><input type="checkbox" required style="width:auto">I consent to being contacted about my application and understand that submission does not guarantee admission.</label><button class="btn btn-primary" type="submit">Submit application →</button></form><div id="enrollMsg"></div></div><div><div class="eyebrow">ENROLLMENT PROCESS</div><h2>Your application journey</h2>${pathways.map((p,i)=>`<div class="step"><div class="number">0${i+1}</div><div><h4>${esc(p.name)}</h4><p>${esc(p.description)}</p></div></div>`).join('')}<div class="notice mt">After applying, the team reviews eligibility, confirms the available intake, shares verified fees, and explains the next step.</div><div class="mt">${a('/fees','View fees and tuition →','btn btn-outline')}</div></div></div></section>`}
function markets(){let cs=state.commodities?.length?state.commodities:crops, ls=state.listings?.length?state.listings:[];return `<section class="market-hero"><div class="container"><div class="logo-line"><img class="market-logo" src="https://static.wixstatic.com/media/92fe26_d7cbb3fcea4045f7a165961d98a4dc69~mv2.png" alt="Markets Online logo"><div class="eyebrow" style="color:#f2cf9b">TSELA YAGWE NETWORK · AGRICULTURE & COMMERCE</div></div><h1 style="margin-top:25px">From the farm to the marketplace.</h1><p>Find agricultural products, explore commodity price indicators and connect with buyers and producers across regional trading corridors.</p><div class="button-row mt">${a('/listings','Browse marketplace →','btn btn-white')}${a('/dashboard','Open trading desk','btn btn-dark-outline')}</div></div></section><section class="section"><div class="container"><div class="flex between wrap"><div><div class="eyebrow">AGRICULTURAL INDICATORS</div><h2>Commodity market pricing</h2><p class="lead">Prices in ZAR per indicated unit, when verified and published by an administrator.</p></div>${a('/prices','View all indicators →','text-link')}</div>${priceTable(cs.slice(0,6))}<div class="notice mt">Prices are not represented as live exchange quotations unless an authenticated data feed is enabled. Blank values mean awaiting a verified update.</div></div></section><section class="section soft"><div class="container"><div class="flex between wrap mb"><div><div class="eyebrow">ECOSYSTEM HUB</div><h2>Trade, source and connect.</h2></div>${a('/listings','Open marketplace →','text-link')}</div><div class="grid grid3"><div class="metric"><div class="eyebrow">COMMERCIAL & SME</div><h3>Agroprocessors</h3><p class="muted">Find businesses transforming crops and livestock into market-ready products.</p></div><div class="metric"><div class="eyebrow">LIVESTOCK & CROPS</div><h3>Farm Produce</h3><p class="muted">Explore crop production, cattle, goats, poultry and other agricultural listings.</p></div><div class="metric"><div class="eyebrow">TRADE & DISTRIBUTION</div><h3>Offtake & Export</h3><p class="muted">Discover sourcing enquiries, supply relationships and cross-border trade opportunities.</p></div></div>${ls.length?`<div class="grid grid3 mt">${ls.slice(0,3).map(listingCard).join('')}</div>`:'<div class="empty mt"><strong>Marketplace listings are opening soon</strong>Verified sellers can publish agricultural lots once the database and moderation process are activated.</div>'}</div></section><section class="section"><div class="container"><div class="cta-box"><div class="eyebrow" style="color:#e8c78f">CONNECT TO THE MARKET</div><h2>Ready to buy, sell or manage commodity lots?</h2><p>Create your free network account to request listing access, view account activities and communicate with market participants.</p>${a('/register','Create a member account →','btn btn-white')}</div></div></section>`}
function priceTable(items){return `<div class="table-wrap"><table class="market-table"><thead><tr><th>Commodity</th><th>Category</th><th>Indicative price</th><th>Last verified</th></tr></thead><tbody>${items.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.category)}</td><td>${c.price_zar!=null?`${formatZar(c.price_zar)} / ${esc(c.unit||'kg')}`:'Awaiting verified data'}</td><td>${c.verified_at?new Date(c.verified_at).toLocaleDateString('en-ZA'):'—'}</td></tr>`).join('')}</tbody></table></div>`}
function prices(){let items=(state.commodities?.length?state.commodities:crops).filter(c=>state.priceFilter==='All'||c.category===state.priceFilter);return `${title('Commodity prices','Commodity market indicators.','Monitor available crop and livestock price indicators and their verification dates.')}<section class="section"><div class="container"><div class="market-toolbar"><button data-price="All" class="btn ${state.priceFilter==='All'?'btn-primary':'btn-outline'} btn-sm">All commodities</button><button data-price="Crops" class="btn ${state.priceFilter==='Crops'?'btn-primary':'btn-outline'} btn-sm">Crops</button><button data-price="Livestock" class="btn ${state.priceFilter==='Livestock'?'btn-primary':'btn-outline'} btn-sm">Livestock</button></div>${priceTable(items)}<div class="notice mt">For price and trade decisions, verify rates, units, location, quality, publication times and seller identity. This site does not currently have a real-time market data subscription.</div></div></section>`}
function listingCard(l){let img=l.image_url&&/^https:\/\//.test(l.image_url)?esc(l.image_url):'/media/'+(['Livestock','Cattle','Goats','Poultry'].includes(l.category)?'cattle-and-goats':'crop-production')+'.webp';return `<article class="feature-card listing-card"><img loading="lazy" src="${img}" alt="${esc(l.title)}"><div class="feature-body"><span class="badge">${esc(l.category||'Agriculture')}</span><h3>${esc(l.title)}</h3><p>${esc(l.description||'Contact the seller for full specifications.')}</p><p class="inline-price">${l.price_zar!=null?formatZar(l.price_zar):'Price on request'} · ${esc(l.location||'Location on enquiry')}</p><button class="btn btn-outline btn-sm" data-enquire="${esc(l.id)}">Enquire about lot →</button></div></article>`}
function listings(){const ls=(state.listings||[]).filter(l=>state.listingFilter==='All'||l.category===state.listingFilter);const empty=`<div class="empty"><strong>No approved live listings yet</strong>Approved listings will appear here after the moderation process is enabled.<div class="mt"><a class="btn btn-primary" href="${wa('Hello, I am interested in agricultural commodity listings on Markets Online.')}" target="_blank" rel="noopener">Enquire via WhatsApp</a></div></div>`;return `${title('Marketplace','Explore agricultural opportunities.','Listings are reviewed before publication. Contact sellers to confirm quality, supply, location and commercial terms.')}<section class="section"><div class="container"><div class="market-toolbar">${['All','Crops','Livestock','Agroprocessing'].map(f=>`<button data-filter="${f}" class="btn ${state.listingFilter===f?'btn-primary':'btn-outline'} btn-sm">${f==='All'?'All listings':f}</button>`).join('')}${a('/dashboard','Post a commodity lot','btn btn-outline btn-sm')}</div>${ls.length?`<div class="grid grid3">${ls.map(listingCard).join('')}</div>`:empty}<div class="notice mt">Marketplace enquiries do not constitute completed purchases. Verify listing information and agree to formal terms directly with verified counterparties.</div></div></section>`}

function contact(){return `${title('Contact Us','Let’s build your next opportunity.','For course admissions, business partnerships, funding discussions and agricultural market enquiries, contact our team.')}<section class="section"><div class="container split" style="align-items:start"><div><div class="eyebrow">CONNECT WITH US</div><h2>We would love to hear from you.</h2><p class="lead">Our coordinators can guide you towards the appropriate course, enrollment pathway or marketplace support channel.</p><div class="contact-pill"><span style="font-size:29px">💬</span><div><strong>WhatsApp and enquiries</strong><a href="${wa()}" target="_blank" rel="noopener">+27 65 150 3974 →</a></div></div><img style="margin-top:26px;border-radius:22px;height:230px;width:100%;object-fit:cover" src="https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=1100&q=82" alt="Team of agribusiness professionals"></div><div class="form-card"><h2>Send an enquiry</h2><form id="contactForm">${field('contact_name','Full name','Your name')}${field('contact_email','Email address','you@example.com','email')}${field('contact_phone','Mobile number','+27 ...','tel',false)}<div class="field"><label for="contact_subject">What can we help with?</label><select id="contact_subject" required><option value="">Choose a topic</option><option>Course Enrollment</option><option>Course Fees</option><option>Course Financing</option><option>Commodity Trading</option><option>Partnership</option><option>Other Enquiry</option></select></div><div class="field"><label for="contact_message">Your message</label><textarea id="contact_message" rows="5" required placeholder="Tell us a little more about your enquiry..."></textarea></div><button class="btn btn-primary">Send enquiry →</button></form><div id="contactMsg"></div></div></div></section>`}
function loginPage(register=false){return `${title(register?'Register':'Member Access',register?'Create your network account.':'Welcome back to your network.','Secure access for members, applicants, commodity traders and administrators.')}<section class="section-sm"><div class="container"><div class="form-card auth-card"><h2>${register?'Join Tsela Yagwe Network':'Sign in to your account'}</h2><p class="muted">${register?'Create a profile to follow enrollments, manage listings and access member features.':'Your account provides access to the member dashboard and secure activity records.'}</p>${!CONNECTED?'<div class="notice">Secure account registration and sign-in will become available when the new Supabase project is connected. You can explore the public preview in the meantime.</div>':''}<form id="authForm">${register?field('auth_name','Full name','Your full name'):''}${field('auth_email','Email address','you@example.com','email')}${field('auth_password','Password',register?'Minimum 8 characters':'Your password','password')}${register?'<p class="fineprint">Use a unique password of at least 8 characters. You may need to verify your email.</p>':''}<button class="btn btn-primary" type="submit" ${!CONNECTED?'disabled':''}>${register?'Create account →':'Sign in →'}</button></form><div id="authMsg" style="margin-top:20px"></div><hr class="separator"><p>${register?'Already registered?':'Need an account?'} ${a(register?'/login':'/register',register?'Sign in':'Register for free','text-link')}</p>${a('/','← Back to the homepage','text-link')}</div></div></section>`}
function dashboard(){if(!CONNECTED)return `${title('Dashboard','Member portal preview','Account data will be displayed once the secure Supabase database has been connected.')}<section class="section"><div class="container"><div class="notice">Supabase is not yet configured. No account access, deposits, withdrawals or fake account balances are enabled.</div><div class="grid grid3 mt"><div class="metric"><div class="metric-label">Commodity listings</div><strong>—</strong><small>Connect database for live records</small></div><div class="metric"><div class="metric-label">Wallet balance</div><strong>—</strong><small>Funds are never simulated</small></div><div class="metric"><div class="metric-label">Enrollment status</div><strong>—</strong><small>Secure member access required</small></div></div><div class="button-row mt">${a('/courses','View courses','btn btn-primary')}${a('/markets','Explore markets','btn btn-outline')}</div></div></section>`;
if(!state.user)return `${title('Member Dashboard','Sign in to continue.','Your activity, enrollments, wallet records and profile are private.')}<section class="section"><div class="container">${a('/login','Secure login →','btn btn-primary')}</div></section>`;
let name=state.profile?.full_name||state.user.email?.split('@')[0]||'Member';let balance=state.wallet?.balance_zar||0, usable=state.wallet?.available_zar||0, bonus=0;
const tab=state.dashTab;const tabs=[['overview','Overview'],['profile','My Profile'],['enrollments','Courses'],['listings','Commodity Lots'],['wallet','Wallet & Capital'],['history','Activity Log']];
let panel='';
if(tab==='overview'){panel=`<div class="grid grid4"><div class="metric"><div class="metric-label">Deposited funds</div><strong>${formatZar(balance)}</strong><small>Actual ledger balance</small></div><div class="metric"><div class="metric-label">Listed commodity</div><strong>${(state.myListings||[]).length}</strong><small>Your submitted lots</small></div><div class="metric"><div class="metric-label">Total balance</div><strong>${formatZar(balance)}</strong><small>No demo credits</small></div><div class="metric"><div class="metric-label">Usable balance</div><strong>${formatZar(usable)}</strong><small>Subject to reconciliation</small></div></div><div class="grid grid2 mt"><div class="dash-pane"><div class="eyebrow">YOUR ACCOUNT</div><h3>Capital actions</h3><p class="muted">Deposit, transfer and withdrawal requests will require administrator verification and a licensed payment provider.</p><div class="button-row">${['Deposit','Transfer','Withdraw'].map(v=>`<button data-capital="${v.toLowerCase()}" class="btn ${v==='Deposit'?'btn-primary':'btn-outline'} btn-sm">${v}</button>`).join('')}</div><p class="fineprint" style="margin-top:17px">No real money can be moved on this preview.</p><button class="text-link" data-tab="history" style="border:0;background:transparent;margin-top:6px">View full transaction history →</button></div><div class="dash-pane"><div class="eyebrow">MARKETPLACE</div><h3>Explore corridor offtake and export lots</h3><p class="muted">Sorghum, livestock and packaged goods for regional buyers — commercial transactions are arranged off-platform until verified integrations are approved.</p>${a('/listings','View opportunities →','btn btn-primary')}</div></div><div class="dash-pane mt"><div class="eyebrow">DEVELOPMENT PROGRAMMES</div><h3>Franchise and investor tracks</h3><p>Build your knowledge and enterprise plan through purposeful training pathways.</p>${a('/enrollment','Apply for a course →','btn btn-outline')}</div>`}
if(tab==='profile')panel=`<div class="dash-pane"><div class="flex between wrap"><h3>Personal information</h3><span class="badge">Member profile</span></div><form id="profileForm">${field('profile_full_name','Full name',name)}${field('profile_phone','Mobile number','+27 ...','tel',false)}<div class="field"><label>Email</label><input value="${esc(state.user.email)}" disabled></div><div class="field"><label for="profile_location">Location</label><input id="profile_location" placeholder="City, country"></div><div class="field"><label for="profile_language">Language preferences</label><input id="profile_language" placeholder="English, Setswana..."></div><button class="btn btn-primary">Save profile</button></form><div id="profileMsg"></div></div>`;
if(tab==='enrollments')panel=`<div class="dash-pane"><div class="flex between wrap"><h3>My course applications</h3>${a('/enrollment','New application','btn btn-primary btn-sm')}</div>${state.enrollments.length?`<div class="table-wrap"><table class="market-table"><thead><tr><th>Course</th><th>Track</th><th>Status</th><th>Date</th></tr></thead><tbody>${state.enrollments.map(x=>`<tr><td>${esc(x.course_slug)}</td><td>${esc(x.pathway)}</td><td><span class="badge ${x.status==='pending'?'pending':''}">${esc(x.status)}</span></td><td>${new Date(x.created_at).toLocaleDateString('en-ZA')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No applications yet</strong>Find a development course and start your enrollment.</div>'}</div>`;
if(tab==='listings')panel=`<div class="grid grid2"><div class="dash-pane"><h3>Submit a commodity listing</h3><p class="muted">Listings are reviewed by an administrator before appearing in the public marketplace.</p><form id="listingForm">${field('lot_title','Lot title','e.g. Maize harvest — 20 tonnes')}<div class="field"><label for="lot_category">Category</label><select id="lot_category"><option>Crops</option><option>Livestock</option><option>Agroprocessing</option></select></div>${field('lot_location','Location','Town / province')}${field('lot_quantity','Quantity / unit','e.g. 20 tonnes')} ${field('lot_price','Asking price (ZAR, optional)','', 'number',false)}<div class="field"><label for="lot_description">Description</label><textarea id="lot_description" rows="4" required></textarea></div><button class="btn btn-primary">Submit for review →</button></form><div id="listingMsg"></div></div><div class="dash-pane"><h3>My commodity lots</h3>${(state.myListings||[]).length?(state.myListings||[]).map(l=>`<div class="history-item"><div class="history-icon">🌾</div><div><strong>${esc(l.title)}</strong><small>${esc(l.category)} • <span class="badge ${l.status==='pending'?'pending':''}">${esc(l.status)}</span></small></div></div>`).join(''):'<div class="empty"><strong>No submitted lots yet</strong>Use the form to add your first approved-market listing.</div>'}</div></div>`;
if(tab==='wallet')panel=`<div class="grid grid2"><div class="dash-pane"><h3>Wallet overview</h3><p class="muted">Your wallet reflects only reconciled financial records. No deposits, credits or balances are simulated.</p><div class="metric"><div class="metric-label">Confirmed funds</div><strong>${formatZar(balance)}</strong><small>Available ${formatZar(usable)}</small></div><div class="button-row mt">${['Deposit','Transfer','Withdraw'].map(v=>`<button data-capital="${v.toLowerCase()}" class="btn ${v==='Deposit'?'btn-primary':'btn-outline'} btn-sm">${v}</button>`).join('')}</div><p class="fineprint mt">Real-money functions are intentionally locked pending regulated payment infrastructure, KYC/AML review and legal approval.</p></div><div class="dash-pane"><h3>Capital request status</h3>${state.capitalRequests.length?state.capitalRequests.map(t=>`<div class="history-item"><div class="history-icon">↗</div><div><strong>${esc(t.action_type)} • ${formatZar(t.amount_zar)}</strong><small>${esc(t.status)} · ${new Date(t.created_at).toLocaleDateString('en-ZA')}</small></div></div>`).join(''):'<div class="empty"><strong>No requests on your account</strong>Requests will appear here once submitted and reviewed.</div>'}</div></div>`;
if(tab==='history')panel=`<div class="dash-pane"><h3>Activity and transaction history</h3>${state.transactions.length?state.transactions.map(t=>`<div class="history-item"><div class="history-icon">↗</div><div><strong>${esc(t.entry_type)} · ${formatZar(t.amount_zar)}</strong><small>${new Date(t.created_at).toLocaleString('en-ZA')} · ${esc(t.status)}</small></div></div>`).join(''):'<div class="empty"><strong>No confirmed transactions</strong>Activity will appear here as real records are created by authorised services.</div>'}</div>`;
return `${title('Member Dashboard',`Welcome back, ${esc(name)}.`, 'Manage your learning, market activity, verified financial records and profile.')}<section class="section-sm"><div class="container"><div class="flex between wrap"><span class="badge">Secure member area</span><div class="button-row">${state.profile?.role==='admin'?a('/admin','Admin Console','btn btn-outline btn-sm'):''}<button id="logout" class="btn btn-outline btn-sm">Sign out</button></div></div><div class="dashboard-nav">${tabs.map(([key,text])=>`<button class="btn ${tab===key?'btn-primary':'btn-outline'} btn-sm" data-tab="${key}">${text}</button>`).join('')}</div>${panel}</div></section>`}

function firstAdminGate(){
  let html='<section class="section-sm"><div class="container"><div class="form-card auth-card"><div class="eyebrow">RESTRICTED AREA</div>';
  if(!state.user){
    html+='<h2>Administrator login</h2><p>Register using an existing Gmail or another email account you can access. Verify the email through the confirmation message, then sign in.</p>';
    html+='<p class="muted">The first verified member with the private one-time setup code may activate the administrator dashboard. The setup code is never published on the website, works only once, and expires after 30 days.</p>';
    html+='<div class="button-row">'+a('/register','Create an account','btn btn-primary')+a('/login','Sign in','btn btn-outline')+'</div>';
  }else{
    html+='<h2>Activate your administrator account</h2><p>Signed in as <strong>'+esc(state.user.email)+'</strong>.</p>';
    html+='<p class="muted">If you have verified your email, enter the private one-time administrator setup code supplied by WebDevPro. This is <strong>not</strong> your account password.</p>';
    html+='<form id="claimAdminForm"><div class="field"><label for="admin_claim_code">One-time administrator setup code</label>';
    html+='<input id="admin_claim_code" type="password" autocomplete="off" minlength="30" placeholder="Enter the private code" required></div>';
    html+='<button class="btn btn-primary" type="submit">Activate administrator access →</button></form>';
    html+='<div id="claimAdminMsg" style="margin-top:18px"></div>';
    html+='<p class="fineprint" style="margin-top:16px">Once the first administrator is activated, new users will have ordinary member access unless an administrator grants them additional permissions.</p>';
  }
  return title('Administration','Secure administrator access','Use your verified email and a private, single-use activation code.')+html+'</div></div></section>';
}

function admin(){if(!CONNECTED)return `${title('Administration','Administrator console','The admin workspace will open when your dedicated Supabase project and first admin identity are set up.')}<section class="section"><div class="container"><div class="notice">Administrative access is never activated using a public default password. After database setup, a verified user will be granted the admin role securely.</div></div></section>`;if(!state.user||state.profile?.role!=='admin')return firstAdminGate();
let t=state.adminTab, tabs=[['enrollments','Applications'],['listings','Marketplace'],['commodities','Market Prices'],['courses','Courses'],['capital','Capital Requests'],['inquiries','Enquiries'],['members','Members']];let pane='';
if(t==='enrollments')pane=`<div class="dash-pane"><h3>Review applications</h3>${adminTable(['Applicant','Course','Track','Status','Manage'],(state.adminEnrollments||[]).map(x=>[esc(x.full_name)+'<small>'+esc(x.email)+'</small>',esc(x.course_slug),esc(x.pathway),esc(x.status),`<button class="btn btn-outline btn-sm" data-approve="enrollments:${esc(x.id)}">Approve</button>`]))}</div>`;
if(t==='listings')pane=`<div class="dash-pane"><h3>Review marketplace listings</h3>${adminTable(['Title','Category','Location','Status','Actions'],(state.adminListings||[]).map(x=>[esc(x.title),esc(x.category),esc(x.location),esc(x.status),`<button class="btn btn-outline btn-sm" data-approve="listings:${esc(x.id)}">Publish</button> <button class="btn btn-red btn-sm" data-reject="listings:${esc(x.id)}">Reject</button>`]))}</div>`;
if(t==='commodities')pane=`<div class="grid grid2"><div class="dash-pane"><h3>Publish a verified price</h3><p class="muted">Record the source and unit before publishing any figure.</p><form id="priceForm"><div class="field"><label for="p_name">Commodity</label><select id="p_name" required>${crops.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></div>${field('p_price','Verified market price (ZAR)','e.g. 65.00','number')} ${field('p_unit','Unit','kg')}${field('p_source','Verified source / market reference','Source reference')}<button class="btn btn-primary">Publish price</button></form><div id="priceMsg"></div></div><div class="dash-pane"><h3>Market price records</h3>${priceTable(state.commodities||crops)}</div></div>`;
if(t==='courses')pane=`<div class="grid grid2"><div class="dash-pane"><h3>Add a course</h3><form id="courseForm">${field('c_title','Course title','New course name')}${field('c_slug','URL slug','course-name')}<div class="field"><label for="c_description">Description</label><textarea id="c_description" required rows="4"></textarea></div>${field('c_duration','Duration / next intake','Schedule on request')} ${field('c_fee','Tuition fee (ZAR, optional)','','number',false)}<button class="btn btn-primary">Publish course</button></form><div id="courseMsg"></div></div><div class="dash-pane"><h3>Published courses</h3>${(state.courses?.length?state.courses:coursesSeed).map(c=>`<div class="history-item"><div class="history-icon">🎓</div><div><strong>${esc(c.title)}</strong><small>${esc(c.slug)}</small></div></div>`).join('')}</div></div>`;
if(t==='capital')pane=`<div class="dash-pane"><h3>Capital requests (approval only)</h3><div class="notice">Review status requests only. This administration page cannot move money or credit a wallet. Payments require a separate audited integration.</div>${adminTable(['Member','Action','Amount','Status','Created'],(state.adminCapital||[]).map(c=>[esc(c.user_id).slice(0,8)+'…',esc(c.action_type),formatZar(c.amount_zar),esc(c.status),new Date(c.created_at).toLocaleDateString('en-ZA')]))}</div>`;
if(t==='inquiries')pane=`<div class="dash-pane"><h3>Contact enquiries</h3>${adminTable(['Name','Topic','Email','Message'],(state.adminInquiries||[]).map(c=>[esc(c.full_name),esc(c.subject),esc(c.email),esc(c.message).slice(0,150)]))}</div>`;
if(t==='members')pane=`<div class="dash-pane"><h3>Registered profiles</h3>${adminTable(['Name','Email','Role','Created'],(state.adminMembers||[]).map(c=>[esc(c.full_name),esc(c.email),esc(c.role),new Date(c.created_at).toLocaleDateString('en-ZA')]))}</div>`;
return `${title('Admin Console','Network administration.','Manage applications, approved listings, verified commodity prices, courses and member enquiries.')}<section class="section-sm"><div class="container"><div class="flex between wrap"><span class="badge">Authorised admin access</span>${a('/dashboard','Member Dashboard','btn btn-outline btn-sm')}</div><div class="dashboard-nav">${tabs.map(([id,name])=>`<button data-admin-tab="${id}" class="btn ${t===id?'btn-primary':'btn-outline'} btn-sm">${name}</button>`).join('')}</div>${pane}</div></section>`}
function adminTable(headers,rows){return rows.length?`<div class="table-wrap"><table class="market-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No records to review</strong>New activity appears here as members submit applications and listings.</div>'}
function notFound(){return `${title('Page not found','That page is not available.','Explore the main website or discover the current range of programmes.')}<section class="section"><div class="container">${a('/','Return home →','btn btn-primary')}</div></section>`}
function render(){const path=state.route;let page=path==='/'?home():path==='/about'?about():path==='/courses'?courses():path==='/fees'?fees():path==='/financing'?financing():path==='/enrollment'?enrollment():path==='/markets'?markets():path==='/prices'?prices():path==='/listings'?listings():path==='/contact'?contact():path==='/register'?loginPage(true):path==='/login'?loginPage():path==='/dashboard'?dashboard():path==='/admin'?admin():notFound();app.innerHTML=header()+`<main id="main" role="main">${page}</main>`+footer()+`<a href="${wa()}" class="whatsapp" target="_blank" rel="noopener" aria-label="Chat on WhatsApp">◉ &nbsp; WhatsApp</a>`;document.title=(path==='/'?'Home':path.split('/')[1].replace(/^./,s=>s.toUpperCase()))+' | Tsela Yagwe Network';setTimeout(fillProfile,0)}
function go(path){if(!path.startsWith('/'))return;history.pushState({},'',path);state.route=path.split('?')[0];scrollTo({top:0,behavior:'instant'});render();if(['/dashboard','/admin'].includes(state.route))loadProtected().then(render)}
function toast(msg){document.querySelector('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),4300)}
function msg(id,text,error=false){let e=document.getElementById(id);if(e)e.innerHTML=`<div class="notice ${error?'error':'success'}" style="margin-top:18px">${esc(text)}</div>`;else toast(text)}
function fillProfile(){if(state.route==='/dashboard'&&state.dashTab==='profile'){const p=state.profile||{};for(let [id,value] of [['profile_full_name',p.full_name],['profile_phone',p.phone],['profile_location',p.location],['profile_language',p.languages]]){let e=document.getElementById(id);if(e)e.value=value||''}}}
// Supabase Auth and PostgREST: public publishable credentials only; policies are enforced server-side.
function authHeaders(extra={}){return {'apikey':KEY,'Authorization':'Bearer '+(state.session?.access_token||KEY),'Content-Type':'application/json',...extra}}
async function authRequest(path,method='POST',payload){if(!CONNECTED)throw Error('The Supabase project is not connected yet.');let r=await fetch(SB+'/auth/v1/'+path,{method,headers:{'apikey':KEY,'Content-Type':'application/json'},body:payload?JSON.stringify(payload):undefined});let json=await r.json().catch(()=>({}));if(!r.ok)throw Error(json.msg||json.error_description||json.message||'Authentication failed');return json}
async function rest(table,{method='GET',query='',data=null,prefer='return=representation'}={}){if(!CONNECTED)throw Error('Supabase is not connected');let url=SB+'/rest/v1/'+table+(query?'?'+query:'');let r=await fetch(url,{method,headers:authHeaders({'Prefer':prefer}),body:data?JSON.stringify(data):undefined});let body=await r.json().catch(()=>null);if(!r.ok)throw Error(body?.message||body?.hint||`Request failed (${r.status})`);return body}
function persistSession(session){state.session=session;localStorage.setItem('tsela.session',JSON.stringify(session))}
async function restoreAuth(){if(!CONNECTED)return;try{let sess=JSON.parse(localStorage.getItem('tsela.session')||'null');if(!sess?.access_token)return;state.session=sess;if(sess.expires_at&&sess.expires_at*1000<Date.now()+60000){sess=await authRequest('token?grant_type=refresh_token','POST',{refresh_token:sess.refresh_token});sess.expires_at=Math.floor(Date.now()/1000)+(sess.expires_in||3600);persistSession(sess)}let r=await fetch(SB+'/auth/v1/user',{headers:authHeaders()});if(!r.ok)throw Error('Expired session');state.user=await r.json();await fetchProfile()}catch(err){localStorage.removeItem('tsela.session');state.session=null;state.user=null;state.profile=null}}
async function fetchProfile(){if(!state.user)return;let p=await rest('profiles',{query:'id=eq.'+encodeURIComponent(state.user.id)+'&select=*'});state.profile=p?.[0]||null}
async function logout(){if(state.session?.access_token)try{await fetch(SB+'/auth/v1/logout',{method:'POST',headers:authHeaders()})}catch(_){}localStorage.removeItem('tsela.session');state.user=null;state.session=null;state.profile=null;go('/login')}
async function loadPublic(){if(!CONNECTED)return;let results=await Promise.allSettled([rest('courses',{query:'select=*&is_active=eq.true&order=sort_order.asc'}),rest('commodities',{query:'select=*&order=name.asc'}),rest('listings',{query:'select=*&status=eq.approved&order=created_at.desc'})]);if(results[0].status==='fulfilled')state.courses=results[0].value;if(results[1].status==='fulfilled')state.commodities=results[1].value;if(results[2].status==='fulfilled')state.listings=results[2].value}
async function loadProtected(){if(!state.user||!CONNECTED)return;let qs=[rest('enrollments',{query:'select=*&user_id=eq.'+state.user.id+'&order=created_at.desc'}),rest('listings',{query:'select=*&owner_id=eq.'+state.user.id+'&order=created_at.desc'}),rest('wallet_accounts',{query:'select=*&user_id=eq.'+state.user.id}),rest('wallet_ledger',{query:'select=*&user_id=eq.'+state.user.id+'&order=created_at.desc'}),rest('capital_requests',{query:'select=*&user_id=eq.'+state.user.id+'&order=created_at.desc'})];let r=await Promise.allSettled(qs);let fields=['enrollments','myListings','wallet','transactions','capitalRequests'];r.forEach((x,i)=>{if(x.status==='fulfilled')state[fields[i]]=fields[i]==='wallet'?(x.value?.[0]||null):(x.value||[])});if(state.profile?.role==='admin'){let tabs=[['adminEnrollments','enrollments'],['adminListings','listings'],['adminCapital','capital_requests'],['adminInquiries','inquiries'],['adminMembers','profiles']];let items=await Promise.allSettled(tabs.map(([_,t])=>rest(t,{query:'select=*&order=created_at.desc&limit=200'})));items.forEach((x,i)=>{if(x.status==='fulfilled')state[tabs[i][0]]=x.value})}}
async function sendEnquiry(payload){if(CONNECTED){await rest('inquiries',{method:'POST',data:payload});return 'Your enquiry was received. The team will contact you.'}window.open(wa(`Hello Tsela Yagwe Network, my name is ${payload.full_name}. Topic: ${payload.subject}. Email: ${payload.email}. Message: ${payload.message}`),'_blank','noopener');return 'WhatsApp has opened with your enquiry ready to send.'}
async function handleSubmit(form){let id=form.id;try{

if(id==='claimAdminForm'){
  if(!state.user||!state.session?.access_token)throw Error('Please sign in and verify your email first.');
  const claimCode=form.querySelector('#admin_claim_code').value.trim();
  if(claimCode.length<30)throw Error('Enter the private one-time administrator setup code.');
  const result=await rest('rpc/claim_initial_admin',{method:'POST',data:{setup_code:claimCode}});
  if(!result?.activated)throw Error('Administrator activation could not be confirmed.');
  form.querySelector('#admin_claim_code').value='';
  await fetchProfile();
  await loadProtected();
  go('/admin');
  render();
  return;
}
if(id==='authForm'){let email=form.querySelector('#auth_email').value.trim(),password=form.querySelector('#auth_password').value;if(id==='authForm'&&state.route==='/register'){if(password.length<8)throw Error('Please use a password of at least eight characters.');let name=form.querySelector('#auth_name').value.trim();let data=await authRequest('signup','POST',{email,password,data:{full_name:name}});if(data.session?.access_token||data.access_token){let sess=data.session||data;sess.expires_at=Math.floor(Date.now()/1000)+(sess.expires_in||3600);persistSession(sess);state.user=data.user||data.session?.user;await fetchProfile();go('/dashboard');await loadProtected();render()}else msg('authMsg','Account created. Please check your email to verify your address, then sign in.');return}let data=await authRequest('token?grant_type=password','POST',{email,password});data.expires_at=Math.floor(Date.now()/1000)+(data.expires_in||3600);persistSession(data);state.user=data.user;await fetchProfile();await loadProtected();go(state.profile?.role==='admin'?'/admin':'/dashboard');return}
if(id==='contactForm'){let payload={full_name:form.querySelector('#contact_name').value,email:form.querySelector('#contact_email').value,phone:form.querySelector('#contact_phone').value,subject:form.querySelector('#contact_subject').value,message:form.querySelector('#contact_message').value};let response=await sendEnquiry(payload);msg('contactMsg',response);form.reset();return}
if(id==='enrollmentForm'){let payload={full_name:form.querySelector('#full_name').value,email:form.querySelector('#email').value,phone:form.querySelector('#mobile').value,course_slug:form.querySelector('#course').value,pathway:form.querySelector('#pathway').value,motivation:form.querySelector('#motivation').value};if(CONNECTED){await rest('enrollments',{method:'POST',data:{...payload,user_id:state.user?.id||null}});msg('enrollMsg','Application submitted. The coordinator will review it and contact you.');form.reset()}else{window.open(wa(`Hello, I wish to enroll. Name: ${payload.full_name}. Email: ${payload.email}. Mobile: ${payload.phone}. Course: ${payload.course_slug}. Pathway: ${payload.pathway}. Interests: ${payload.motivation}`),'_blank','noopener');msg('enrollMsg','WhatsApp opened with the application details ready to send. No application was stored on this demo.')}return}
if(!state.user)throw Error('Please sign in before making changes.');
if(id==='profileForm'){let payload={full_name:form.querySelector('#profile_full_name').value,phone:form.querySelector('#profile_phone').value,location:form.querySelector('#profile_location').value,languages:form.querySelector('#profile_language').value};await rest('profiles',{method:'PATCH',query:'id=eq.'+state.user.id,data:payload});await fetchProfile();msg('profileMsg','Profile saved.');return}
if(id==='listingForm'){let payload={owner_id:state.user.id,title:form.querySelector('#lot_title').value,category:form.querySelector('#lot_category').value,location:form.querySelector('#lot_location').value,quantity_text:form.querySelector('#lot_quantity').value,price_zar:form.querySelector('#lot_price').value?Number(form.querySelector('#lot_price').value):null,description:form.querySelector('#lot_description').value,status:'pending'};await rest('listings',{method:'POST',data:payload});await loadProtected();render();toast('Your commodity lot was submitted for administrator review.');return}
if(state.profile?.role!=='admin')throw Error('Administrator access is required.');
if(id==='priceForm'){let name=form.querySelector('#p_name').value;let cat=crops.find(c=>c.name===name)?.category||'Crops';await rest('commodities',{method:'POST',data:{name,category:cat,price_zar:Number(form.querySelector('#p_price').value),unit:form.querySelector('#p_unit').value,source_note:form.querySelector('#p_source').value,verified_at:new Date().toISOString()},prefer:'resolution=merge-duplicates,return=representation'});await loadPublic();render();toast('Market indicator updated.');return}
if(id==='courseForm'){await rest('courses',{method:'POST',data:{title:form.querySelector('#c_title').value,slug:form.querySelector('#c_slug').value,short_description:form.querySelector('#c_description').value,duration:form.querySelector('#c_duration').value,fee:form.querySelector('#c_fee').value?Number(form.querySelector('#c_fee').value):null,is_active:true}});await loadPublic();render();toast('Course added.');return}
}catch(e){msg(({authForm:'authMsg',contactForm:'contactMsg',enrollmentForm:'enrollMsg',profileForm:'profileMsg',listingForm:'listingMsg',priceForm:'priceMsg',courseForm:'courseMsg',claimAdminForm:'claimAdminMsg'})[id]||'',e.message||'Unable to complete this request',true)}}
// Event delegation ensures route transitions and forms work after re-render.
document.addEventListener('click',async e=>{
let link=e.target.closest('a[data-link]');if(link){e.preventDefault();go(new URL(link.href).pathname+new URL(link.href).search);return}
let toggle=e.target.closest('#menuButton');if(toggle){let drawer=document.getElementById('mobileDrawer');drawer?.classList.toggle('hide');toggle.setAttribute('aria-expanded',String(!drawer?.classList.contains('hide')));return}
let tab=e.target.closest('[data-tab]');if(tab){state.dashTab=tab.dataset.tab;render();return}
let adm=e.target.closest('[data-admin-tab]');if(adm){state.adminTab=adm.dataset.adminTab;render();return}
let p=e.target.closest('[data-price]');if(p){state.priceFilter=p.dataset.price;render();return}
let f=e.target.closest('[data-filter]');if(f){state.listingFilter=f.dataset.filter;render();return}
if(e.target.closest('#logout')){logout();return}
let cap=e.target.closest('[data-capital]');if(cap){toast('Real-money '+cap.dataset.capital+' actions are unavailable until the licensed payment and compliance setup is approved.');return}
let ent=e.target.closest('[data-enquire]');if(ent){let l=(state.listings||[]).find(x=>x.id===ent.dataset.enquire);window.open(wa('Hello, I would like to enquire about the commodity lot: '+(l?.title||'listed commodity')),'_blank','noopener');return}
let btn=e.target.closest('[data-approve],[data-reject]');if(btn){if(state.profile?.role!=='admin')return;let [table,id]=(btn.dataset.approve||btn.dataset.reject).split(':');let isApprove=Boolean(btn.dataset.approve);let status=table==='listings'?(isApprove?'approved':'rejected'):(isApprove?'approved':'rejected');if(!confirm('Confirm '+status+' for this '+table+' record?'))return;try{await rest(table,{method:'PATCH',query:'id=eq.'+id,data:{status}});await Promise.all([loadPublic(),loadProtected()]);render();toast('Record updated.')}catch(err){toast(err.message)}return}
});
document.addEventListener('submit',e=>{if(e.target.matches('#authForm,#contactForm,#enrollmentForm,#profileForm,#listingForm,#priceForm,#courseForm,#claimAdminForm')){e.preventDefault();let btn=e.target.querySelector('button[type=submit],button:not([type])');if(btn){btn.disabled=true}handleSubmit(e.target).finally(()=>{if(btn)btn.disabled=false})}});
window.addEventListener('popstate',()=>{state.route=location.pathname;render();if(['/dashboard','/admin'].includes(state.route))loadProtected().then(render)});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e});
async function init(){await restoreAuth();await loadPublic();if(state.user)await loadProtected();state.route=location.pathname;render();if('serviceWorker'in navigator&&location.hostname!=='localhost')navigator.serviceWorker.register('/sw.js').catch(()=>{});}init().catch(err=>{console.error(err);render()});